1	package main
2	
3	import (
4		"errors"
5		"flag"
6		"fmt"
7		"os"
8	
9		"github.com/asdhoaiqqq/zkcircuit-workbench/zkcircuit"
10	)
11	
12	// Process exit codes for the data commands.
13	const (
14		exitOK    = 0
15		exitRule  = 1 // business rule failure (not found, conflict, frozen, …)
16		exitUsage = 2 // bad command line
17		exitData  = 3 // storage cannot be read safely (corrupt/truncated/bad format)
18	)
19	
20	// dataCommands is the set of commands backed by a persistent data directory.
21	var dataCommands = map[string]bool{
22		"circuit-create":    true,
23		"circuit-update":    true,
24		"circuit-freeze":    true,
25		"circuit-get":       true,
26		"circuit-list":      true,
27		"setup-record":      true,
28		"setup-get":         true,
29		"job-submit":        true,
30		"job-get":           true,
31		"job-list":          true,
32		"constraint-import": true,
33		"circuit-compile":   true,
34		"input-check":       true,
35	}
36	
37	// dispatchDataCommand runs cmd with args. handled is false when cmd is not a
38	// data command, so the caller keeps the historical "unknown command" path.
39	func dispatchDataCommand(cmd string, args []string) (code int, handled bool) {
40		if !dataCommands[cmd] {
41			return exitUsage, false
42		}
43		return runDataCommand(cmd, args), true
44	}
45	
46	func runDataCommand(cmd string, args []string) int {
47		fs, f := newFlagSet(cmd, os.Stderr)
48		if err := fs.Parse(args); err != nil {
49			return exitUsage
50		}
51		// Record which value flags were explicitly provided, so circuit-update
52		// can distinguish "omitted" from "given a default value".
53		fs.Visit(func(fl *flag.Flag) {
54			switch fl.Name {
55			case "constraints":
56				f.constraintsSet = true
57			case "public-inputs":
58				f.publicInSet = true
59			case "private-inputs":
60				f.privateInSet = true
61			case "description":
62				f.descriptionSet = true
63			}
64		})
65		if len(fs.Args()) > 0 {
66			fmt.Fprintf(os.Stderr, "error: %s does not accept positional arguments (got %q)\n", cmd, fs.Args()[0])
67			return exitUsage
68		}
69		if f.dir == "" {
70			fmt.Fprintf(os.Stderr, "error: --dir is required for %s\n", cmd)
71			return exitUsage
72		}
73	
74		switch cmd {
75		case "circuit-create":
76			return cmdCircuitCreate(f)
77		case "circuit-update":
78			return cmdCircuitUpdate(f)
79		case "circuit-freeze":
80			return cmdCircuitFreeze(f)
81		case "circuit-get":
82			return cmdCircuitGet(f)
83		case "circuit-list":
84			return cmdCircuitList(f)
85		case "setup-record":
86			return cmdSetupRecord(f)
87		case "setup-get":
88			return cmdSetupGet(f)
89		case "job-submit":
90			return cmdJobSubmit(f)
91		case "job-get":
92			return cmdJobGet(f)
93		case "job-list":
94			return cmdJobList(f)
95		case "constraint-import":
96			return cmdConstraintImport(f)
97		case "circuit-compile":
98			return cmdCircuitCompile(f)
99		case "input-check":
100			return cmdInputCheck(f)
101		}
102		return exitUsage
103	}
104	
105	func requireNameVersion(cmd string, f *cliFlags) (bool, int) {
106		if f.name == "" {
107			fmt.Fprintf(os.Stderr, "error: --name is required for %s\n", cmd)
108			return false, exitUsage
109		}
110		if f.version <= 0 {
111			fmt.Fprintf(os.Stderr, "error: --version must be a positive integer for %s\n", cmd)
112			return false, exitUsage
113		}
114		return true, exitOK
115	}
116	
117	func openStore(f *cliFlags) (*zkcircuit.Store, int) {
118		store, err := zkcircuit.Open(f.dir)
119		if err != nil {
120			return nil, reportStoreError(err)
121		}
122		return store, exitOK
123	}
124	
125	// reportStoreError prints a failed storage/domain call and returns the exit
